sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {


    //MSSOTIQUBE-1244 --> System property to control logging 
    var enableLogging = gs.getProperty('x_hsb11_hsbc_mss_o.el_inbound_event_full_logging') == 'true';

    /*try {

		//MSSOTIQUBE-235 
        var hostHeader = request.getHeader('Host');
        var checkHeader = new global.HSBC_Host_Header_Check();
        var hasHost = checkHeader.hasHostHeader(hostHeader);

        //MSSOTIQUBE-235 - Host Header Checks for authorization
        if (hasHost) {
            response.setStatus(403);
            response.setBody({
                error: 'Unauthorised Host header detected.'
            });
            //MSSOTIQUBE-1244 --> Logging error
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Unauthorised Host header detected.");
            return;
        }
    } catch (error) {
        gs.error("Scripted REST API Resource- el_inbound_event_full: Error while resolving the HOST" + error.message);
        return;
    }*/

    //MSSOTIQUBE-1244  --> Adding try-catch for error handling
    try {
        // initializing; extracting data from the request body
        var grEmail, grWidget, eventsArray = [],
            requestBody = request.body.data.HEADER,
            pay = request.body.data.PAYLOAD,
            requestData = requestBody;

        // Mandatory Field checks and logging of error if missing or invalid fields 
        if (requestData.messageid == '' || requestData.messageid == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Message Id'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing MessageID for this widget inbound record");
            return;
        }
        if (requestData.eventtype == '' || requestData.eventtype == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Type'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing EventType for the record with MessageID: " + requestData.messageid);
            return;
        }
        if (requestData.source == '' || requestData.source == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Source'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing Source for the record with MessageID: " + requestData.messageid);
            return;
        }
        if (requestData.objectid == '' || requestData.objectid == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Id'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing Object Id for the record with MessageID: " + requestData.messageid);
            return;
        }
        if (requestData.objecttype == '' || requestData.objecttype == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Type'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing Object Type for the record with MessageID: " + requestData.messageid);
            return;
        }
        if (requestData.objectidtype == '' || requestData.objectidtype == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Id Type'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing Object Id Type for the record with MessageID: " + requestData.messageid);
            return;
        }
        if (requestData.objectversion == '' || requestData.objectversion == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Version'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing Object Version for the record with MessageID: " + requestData.messageid);
            return;
        }
        if (requestData.eventstatus == '' || requestData.eventstatus == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Status'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing Event Status for the record with MessageID: " + requestData.messageid);
            return;
        }
        if (requestData.eventdatetime == '' || requestData.eventdatetime == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Date Time'));
            //MSSOTIQUBE-1244
            if (enableLogging)
                gs.info("Scripted REST API Resource- el_inbound_event_full: Validation failed: Missing Event Date Time for the record with MessageID: " + requestData.messageid);
            return;
        }

        //Processing record based on source
        if (requestData.source == 'QTRACK') {
            grEmail = new GlideRecord('x_hsb11_hsbc_mss_o_mss_email_inbound');
            grEmail.addQuery('message_id', requestData.messageid);
            grEmail.addQuery('source', requestData.source);
            grEmail.query();
            //Check for duplicate entry
            if (grEmail.next()) {
                response.setError(new sn_ws_err.BadRequestError('Duplicate Entry.'));
                response.setStatus(400);

                //MSSOTIQUBE-1244
                if (enableLogging)
                    gs.info("Scripted REST API Resource- el_inbound_event_full: Error: Rejected due to having a duplicate Message ID:" + requestData.messageid);
                return;

            } else { //Insert new record in qtrack email inbound table
                grEmail = new GlideRecord('x_hsb11_hsbc_mss_o_mss_email_inbound');
                grEmail.initialize();
                grEmail.object_id = requestData.objectid;
                grEmail.object_version = requestData.objectversion;
                grEmail.object_type = requestData.objecttype;
                grEmail.object_id_type = requestData.objectidtype;
                grEmail.event_status = requestData.eventstatus;
                grEmail.event_date_time = requestData.eventdatetime;
                grEmail.source = requestData.source;
                grEmail.message_id = requestData.messageid;
                grEmail.event_type = requestData.eventtype;
                grEmail.additional_attributes = requestData.additionalattributes;
                grEmail.payload = JSON.stringify(pay);

                //MSSOTIQUBE-1244 If error occurs during the database insert, log error and send xmatter alert, else send response 200
                //MSSOTIQUBE-1544 uplift the xmatter severity
                if (!grEmail.insert()) {
                    gs.error('Scripted REST API Resource- el_inbound_event_full: QTRACK Inbound record insert failed from api el_inbound_event_full, event messageid:' + requestData.messageid + ', objectid:' + requestData.objectid + ', eventstatus:' + requestData.eventstatus);
                    failureDescription = "Equities QTrack Inbound record insert failure, event messageid - " + requestData.messageid; + ", objectid - " + requestData.objectid + ", eventstatus - " + requestData.eventstatus;
                    createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_QTRACkInbound');
                    response.setStatus(500);
                    eventsArray.push({
                        'messageId': requestData.messageid,
                        'errorMessage': 'QTRACK Inbound record insert failed.',
                        'status': 'failure'
                    });
                } else {
                    eventsArray.push({
                        'status': '200'
                    });
                }

            }

        } else { //Symphony or SWB inbound
            grWidget = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grWidget.addQuery('message_id', requestData.messageid);
            grWidget.addQuery('source', requestData.source);
            grWidget.query();
            //Check for duplicate entry
            if (grWidget.next()) {
                response.setError(new sn_ws_err.BadRequestError('Duplicate Entry.'));
                response.setStatus(400);

                //MSSOTIQUBE-1244
                if (enableLogging)
                    gs.info("Scripted REST API Resource- el_inbound_event_full: Error: Rejected due to having a duplicate Message ID:" + requestData.messageid);
                return;

            } else { //Insert new record in the widget inbound table for symphony / SWB
                grWidget = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
                grWidget.initialize();
                grWidget.object_id = requestData.objectid;
                grWidget.object_version = requestData.objectversion;
                grWidget.object_type = requestData.objecttype;
                grWidget.object_id_type = requestData.objectidtype;
                grWidget.event_status = requestData.eventstatus;
                grWidget.event_date_time = requestData.eventdatetime;
                grWidget.source = requestData.source;
                grWidget.message_id = requestData.messageid;
                grWidget.event_type = requestData.eventtype;
                grWidget.additional_attributes = requestData.additionalattributes;
                grWidget.payload = JSON.stringify(pay);

                //MSSOTIQUBE-1244 If error occurs during the database insert, log error and send xmatter alert, else send response 200
                //MSSOTIQUBE-1544 uplift the xmatter severity
                if (!grWidget.insert()) {
                    gs.error('Scripted REST API Resource- el_inbound_event_full: Symohony/SWB Widget inbound record insert failed from api el_inbound_event_full, event messageid:' + requestData.messageid + ', objectid:' + requestData.objectid + ', eventstatus:' + requestData.eventstatus);
                    failureDescription = "Equities Symohony/SWB Widget Inbound record insert failure, event messageid - " + requestData.messageid; + " objectid - " + requestData.objectid + " eventstatus - " + requestData.eventstatus;
                    createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_WidgetInbound');
                    response.setStatus(500);
                    eventsArray.push({
                        'messageId': requestData.messageid,
                        'errorMessage': 'Widget Inbound record insert failed.',
                        'status': 'failure'
                    });
                } else {
                    eventsArray.push({
                        'status': '200',
                    });
                }

            }
        }

        response.setBody(eventsArray);

    } catch (error) {
        //MSSOTIQUBE-1544 add error log and send MAJOR xmatter alert
        gs.error("Unexpected error from scripted rest api el_inbound_event_full, Name: " + error.name + ", Message: " + error.message);
        failureDescription = "iQube Equities unexpected error from Widget Inbound scripted rest api el_inbound_event_full, Name: " + error.name + ", Message: " + error.message;
        createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_WidgetInbound');
        response.setStatus(500);
        response.setBody({
            'errorMessage': 'unexpected error Name: ' + error.name + 'Message: ' + error.message,
            'status': 'failure'
        });
    }

})(request, response);
